#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <limits.h>

// Compute floor division for signed long long values.
static long long floor_div(long long a, long long b) {
    // b must be non‑zero.
    long long q = a / b;
    long long r = a % b;
    // In C, division truncates toward zero. Adjust when remainder has opposite sign.
    if (r != 0 && ((r < 0) != (b < 0))) {
        q -= 1;
    }
    return q;
}

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }

    char *end1, *end2;
    errno = 0;
    long long num = strtoll(argv[1], &end1, 10);
    long long den = strtoll(argv[2], &end2, 10);

    // Bad input if conversion failed or extra characters remain.
    if (errno != 0 || *end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (den == 0) {
        puts("ERROR");
        return 0;
    }

    if (llabs(den) > 100000) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    // Determine sign of the overall fraction.
    int negative = (num < 0) ^ (den < 0);
    // Work with absolute values for the Euclidean algorithm.
    long long a = llabs(num);
    long long b = llabs(den);

    // Store terms of the continued fraction.
    long long terms[200];
    int count = 0;

    while (b != 0) {
        if (count >= 200) { // more than 199 terms is an error.
            puts("ERROR");
            return 0;
        }
        long long q = floor_div(a, b);
        terms[count++] = q;
        long long r = a - q * b; // remainder, always non‑negative and less than b.
        a = b;
        b = r;
    }

    // Output in the form [q0; q1, q2, ...]
    putchar('[');
    if (negative) putchar('-');
    if (count > 0) {
        printf("%lld", terms[0]);
    }
    if (count > 1) {
        printf("; ");
        for (int i = 1; i < count; ++i) {
            printf("%lld", terms[i]);
            if (i + 1 < count) printf(", ");
        }
    }
    puts("]");
    return 0;
}
